<?php $page_title='Checkout';include 'partials/header.php';require_login();if(empty($_SESSION['cart'])){header('Location: cart.php');exit;}$err='';$discount=0;$code='';if($_SERVER['REQUEST_METHOD']==='POST'){$address=trim($_POST['address']);$payment=$_POST['payment'];$code=strtoupper(trim($_POST['coupon']??''));$total=cart_total();if($code){$st=$conn->prepare('SELECT * FROM coupons WHERE code=? AND active=1');$st->bind_param('s',$code);$st->execute();$cp=$st->get_result()->fetch_assoc();if($cp && $total >= $cp['min_purchase'])$discount=$total*$cp['discount_percent']/100;else $err='Kupon tidak valid atau minimum belanja belum terpenuhi.';}if(!$err && isset($_POST['place_order'])){$grand=$total-$discount;$uid=$_SESSION['user']['id'];$conn->begin_transaction();try{$o=$conn->prepare('INSERT INTO orders(user_id,total,discount,grand_total,payment_method,shipping_address) VALUES(?,?,?,?,?,?)');$o->bind_param('idddss',$uid,$total,$discount,$grand,$payment,$address);$o->execute();$oid=$conn->insert_id;foreach($_SESSION['cart'] as $i){$sub=$i['price']*$i['qty'];$oi=$conn->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,qty,subtotal) VALUES(?,?,?,?,?,?)');$oi->bind_param('iisdid',$oid,$i['id'],$i['name'],$i['price'],$i['qty'],$sub);$oi->execute();$up=$conn->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$up->bind_param('iii',$i['qty'],$i['id'],$i['qty']);$up->execute();} $conn->commit();unset($_SESSION['cart']);header('Location: orders.php?success=1');exit;}catch(Throwable $e){$conn->rollback();$err='Gagal membuat pesanan.';}}} $total=cart_total();$grand=$total-$discount;?><section class="section container"><div class="cart-layout"><div class="panel"><h2>Informasi Pengiriman</h2><?php if($err):?><div class="alert"><?=$err?></div><?php endif;?><form method="post"><div class="form-group"><label>Alamat lengkap</label><textarea name="address" rows="5" required></textarea></div><div class="form-group"><label>Metode Pembayaran</label><select name="payment"><option>Transfer Bank</option><option>COD</option><option>E-Wallet</option></select></div><div class="form-group"><label>Kode Promo</label><input class="input" name="coupon" value="<?=htmlspecialchars($code)?>" placeholder="Contoh: WELCOME10"></div><button class="btn ghost" name="apply" value="1">Terapkan Promo</button><button class="btn" name="place_order" value="1">Buat Pesanan</button></form></div><div class="panel" style="height:max-content"><h3>Ringkasan Pesanan</h3><div class="summary-row"><span>Subtotal</span><b><?=rupiah($total)?></b></div><div class="summary-row"><span>Diskon</span><b>-<?=rupiah($discount)?></b></div><div class="summary-row total"><span>Total</span><span><?=rupiah($grand)?></span></div></div></div></section><?php include 'partials/footer.php';?>
